class CGameServerStats final : public ISteamGameServerStats {
public:
	// true on the game-server-side instance (registry <Iface>GS_()): the same class serves both paths, but e.g. P2P must send/receive with the game-server identity there.
	bool m_gs = false;
	SteamAPICall_t RequestUserStats(CSteamID steamIDUser) override { EMU_LOG("ISteamGameServerStats::RequestUserStats"); GSStatsReceived_t r{}; r.m_eResult = k_EResultOK; r.m_steamIDUser = steamIDUser; return emu::QueueGameServerCallResult(r); }
	bool GetUserStat(CSteamID steamIDUser, const char * pchName, int32 * pData) override { EMU_LOG("ISteamGameServerStats::GetUserStat"); return emu::SvStats().GetInt(steamIDUser, pchName, pData); }
	bool GetUserStat(CSteamID steamIDUser, const char * pchName, float * pData) override { EMU_LOG("ISteamGameServerStats::GetUserStat"); return emu::SvStats().GetFloat(steamIDUser, pchName, pData); }
	bool GetUserAchievement(CSteamID steamIDUser, const char * pchName, bool * pbAchieved) override { EMU_LOG("ISteamGameServerStats::GetUserAchievement"); return emu::SvStats().GetAch(steamIDUser, pchName, pbAchieved); }
	bool SetUserStat(CSteamID steamIDUser, const char * pchName, int32 nData) override { EMU_LOG("ISteamGameServerStats::SetUserStat"); return emu::SvStats().SetInt(steamIDUser, pchName, nData); }
	bool SetUserStat(CSteamID steamIDUser, const char * pchName, float fData) override { EMU_LOG("ISteamGameServerStats::SetUserStat"); return emu::SvStats().SetFloat(steamIDUser, pchName, fData); }
	bool UpdateUserAvgRateStat(CSteamID steamIDUser, const char * pchName, float flCountThisSession, double dSessionLength) override { EMU_LOG("ISteamGameServerStats::UpdateUserAvgRateStat"); return {};  }
	bool SetUserAchievement(CSteamID steamIDUser, const char * pchName) override { EMU_LOG("ISteamGameServerStats::SetUserAchievement"); return emu::SvStats().SetAch(steamIDUser, pchName, true); }
	bool ClearUserAchievement(CSteamID steamIDUser, const char * pchName) override { EMU_LOG("ISteamGameServerStats::ClearUserAchievement"); return emu::SvStats().SetAch(steamIDUser, pchName, false); }
	SteamAPICall_t StoreUserStats(CSteamID steamIDUser) override { EMU_LOG("ISteamGameServerStats::StoreUserStats"); GSStatsStored_t r{}; r.m_eResult = k_EResultOK; r.m_steamIDUser = steamIDUser; return emu::QueueGameServerCallResult(r); }
};

